-- State transitions declared for Department (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION organization.departments_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'inactive'), ('inactive', 'active'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: departments.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS departments_status_transition_check ON organization.departments;
CREATE TRIGGER departments_status_transition_check
    BEFORE UPDATE OF "status" ON organization.departments
    FOR EACH ROW EXECUTE FUNCTION organization.departments_status_transition_check();
